function dayKey(iso:string,timeZone:string,precision='timestamp'){return ['date','date_only'].includes(precision)?iso.slice(0,10):new Intl.DateTimeFormat('en-CA',{timeZone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(iso));}
function shiftDay(date:string,days:number){return new Date(Date.parse(date+'T00:00:00Z')+days*86400000).toISOString().slice(0,10);}
export function DesktopTimeline({companyId}:{companyId?:string}){return <TimelineContent key={companyId??'picker'} companyId={companyId}/>;}
function TimelineContent({companyId}:{companyId?:string}){
 const {text:t,value}=usePrefs(),router=useRouter(),[query,setQuery]=useState(''),[search,setSearch]=useState('');
 const catalog=useData({action:'catalog',p:{kind:'company',q:search,limit:50}},catalogSchema),company=useData(companyId?{action:'company',p:{id:companyId}}:null,companyDetailSchema);
 useEffect(()=>{const timer=setTimeout(()=>setSearch(query.trim()),250);return()=>clearTimeout(timer);},[query]);
 const stock=company.data?.company,choices=catalog.data?.items??[];
 return <div className="pc-research pc-timeline"><Crumbs><Link href="/timeline">{t('기업 타임라인','Company timeline')}</Link>{stock&&<><span>›</span><strong>{stock.title}</strong></>}</Crumbs>
 {!companyId&&<PcHeading title={t('기업 타임라인','Company timeline')} description={t('지원 기업을 선택해 게시된 변화를 시간순으로 확인하세요.','Choose a supported company to follow published changes over time.')}/>}
 <PcDataState {...company} retry={company.reload}/>{stock&&company.data&&<TimelineHero data={company.data} reload={company.reload}/>}
 {stock&&<nav className="pc-research-tabs" aria-label={t('기업 탐색','Company navigation')}><Link href={'/companies/'+stock.id}>{t('기업 개요','Overview')}</Link><Link href={'/companies/'+stock.id+'?tab=chart'}>{t('주가 차트','Price chart')}</Link><span aria-current="page">{t('기업 타임라인','Company timeline')}</span><Link href={'/search?q='+encodeURIComponent(stock.ticker)+'&kind=document'}>{t('재무 정보','Financial sources')}</Link><Link href={'/search?q='+encodeURIComponent(stock.ticker)+'&kind=event'}>{t('실적','Events')}</Link><Link href={'/search?q='+encodeURIComponent(stock.ticker)+'&kind=document'}>{t('리서치','Research')}</Link></nav>}
 <div className="pc-timeline-picker"><label><Icon name="search" size={18}/><input aria-label={t('기업명 또는 종목코드 검색','Search company or ticker')} value={query} maxLength={100} placeholder={t('기업명 또는 종목코드','Company or ticker')} onChange={e=>setQuery(e.target.value)}/></label><label><span className="pc-research-sr">{t('타임라인 기업 선택','Timeline company')}</span><select aria-label={t('타임라인 기업 선택','Timeline company')} value={companyId??''} disabled={catalog.loading} onChange={e=>router.push(e.target.value?'/companies/'+encodeURIComponent(e.target.value)+'/timeline':'/timeline')}><option value="">{t('기업 선택','Choose a company')}</option>{stock&&!choices.some(item=>item.id===stock.id)&&<option value={stock.id}>{stock.title+' ('+stock.ticker+')'}</option>}{choices.map(item=><option value={item.id} key={item.id}>{item.title+' ('+item.ticker+')'}</option>)}</select></label></div><PcDataState {...catalog} retry={catalog.reload}/>
 {companyId&&stock&&company.data?<TimelineBody key={companyId+':'+value.timezone} company={company.data}/>:!companyId?<PcEmpty title={t('변화를 확인할 기업을 선택하세요','Choose a company')} description={t('기간과 이벤트 유형을 선택해 공식 자료의 변화를 확인할 수 있습니다.','Filter published events by date and type.')}/>:null}</div>;
}
function TimelineHero({data,reload}:{data:CompanyDetail;reload:()=>void}){const {token}=useAuth(),{text:t}=usePrefs(),action=useMutation();return <><section className="pc-timeline-hero"><PcLogo ticker={data.company.ticker} size={88}/><div><h1>{data.company.title}<span>{data.company.ticker}</span></h1><p>{data.company.summary||data.company.market}</p></div><Quote ticker={data.company.ticker}/><button className="pc-button pc-secondary" aria-pressed={data.watching} disabled={action.busy} onClick={()=>void action.run(async()=>{await request('/v1/watchlist/'+encodeURIComponent(data.company.id),token,emptySchema,body(data.watching?'DELETE':'PUT'));reload();})}><Icon name="star"/>{data.watching?t('관심종목 등록됨','Watching'):t('관심종목 추가','Add to watchlist')}</button></section><PcNotice action={action}/></>;}
function TimelineBody({company}:{company:CompanyDetail}){
 const {text:t,value,date}=usePrefs(),[today]=useState(()=>dayKey(new Date().toISOString(),value.timezone)),[from,setFrom]=useState(()=>shiftDay(today,-365)),[until,setUntil]=useState(today),[range,setRange]=useState({from,until}),[rangeError,setRangeError]=useState(''),[type,setType]=useState(''),[sort,setSort]=useState('newest');
 const days=Math.max(1,Math.min(1095,Math.ceil((Date.parse(today+'T00:00:00Z')-Date.parse(range.from+'T00:00:00Z'))/86400000)+1));
 const result=useResource('/v1/companies/'+encodeURIComponent(company.company.id)+'/timeline?days='+days+'&limit=100',eventsSchema);
 const calendar=useResource('/v1/calendar?from_date='+today+'&until_date='+shiftDay(today,365),calendarSchema);
 const matching=(result.data??[]).filter(event=>event.company.id===company.company.id&&dayKey(event.published_at,value.timezone,event.publication_precision)>=range.from&&dayKey(event.published_at,value.timezone,event.publication_precision)<=range.until);
 const types=[...new Set(matching.map(event=>event.event_type))],activeType=types.includes(type)?type:'',events=matching.filter(event=>!activeType||event.event_type===activeType).sort((a,b)=>(sort==='oldest'?1:-1)*(Date.parse(a.published_at)-Date.parse(b.published_at))||a.id.localeCompare(b.id));
 const nextDates=(calendar.data??[]).filter(item=>item.company_id===company.company.id&&item.occurs_on>=today).sort((a,b)=>a.occurs_on.localeCompare(b.occurs_on));
 const formId=useId();
 return <><div className="pc-timeline-filters"><form className="pc-timeline-range" onSubmit={event=>{event.preventDefault();if(!from||!until||from>until||from<shiftDay(today,-1094)||until>today){setRangeError(t('최근 3년 안에서 시작일과 종료일을 확인하세요.','Choose a valid range within the last three years.'));return;}setRangeError('');setRange({from,until});setType('');}}><Icon name="calendar"/><label htmlFor={formId+'-from'} className="pc-research-sr">{t('타임라인 시작일','Timeline start date')}</label><input id={formId+'-from'} type="date" required min={shiftDay(today,-1094)} max={until} value={from} onChange={e=>setFrom(e.target.value)}/><span>~</span><label htmlFor={formId+'-until'} className="pc-research-sr">{t('타임라인 종료일','Timeline end date')}</label><input id={formId+'-until'} type="date" required min={from} max={today} value={until} onChange={e=>setUntil(e.target.value)}/><button type="submit">{t('기간 적용','Apply dates')}</button></form><div className="pc-timeline-types" role="group" aria-label={t('이벤트 유형','Event type')}><button aria-pressed={!activeType} onClick={()=>setType('')}>{t('전체','All')} ({matching.length})</button>{types.map(item=><button key={item} aria-pressed={activeType===item} onClick={()=>setType(item)}><EventTag type={item}/><span>({matching.filter(event=>event.event_type===item).length})</span></button>)}</div></div>{rangeError&&<p role="alert" className="pc-research-error">{rangeError}</p>}
 <div className="pc-research-columns pc-timeline-columns"><PcPanel title={t('주요 이벤트 타임라인','Key event timeline')} icon="timeline" action={<div className="pc-timeline-count"><span>{t('총 ','')+events.length+t('개의 이벤트',' events')}</span><select aria-label={t('타임라인 정렬','Timeline sort')} value={sort} onChange={e=>setSort(e.target.value)}><option value="newest">{t('최신순','Newest first')}</option><option value="oldest">{t('오래된순','Oldest first')}</option></select></div>}><p className="pc-research-muted">{t('주요 소식과 기업의 변화를 시간순으로 확인하세요.','Follow published company changes in chronological order.')}</p><PcDataState {...result} retry={result.reload}/>{!result.loading&&!result.error&&<div className="pc-timeline-events">{events.map(event=><article className={'pc-timeline-item pc-timeline-type-'+event.event_type} key={event.id}><time dateTime={event.published_at}>{date(event.published_at,event.publication_precision)}</time><span className="pc-timeline-node"/><Link className="pc-timeline-thumb" href={'/events/'+event.id} aria-label={event.headline}><PcLogo ticker={event.company.ticker} size={88}/></Link><div><Link className="pc-timeline-event-title" href={'/events/'+event.id}><h2>{event.headline}</h2></Link><p>{event.what_happened}</p><SourceLink url={event.source_url}>{event.source_provider.toUpperCase()}</SourceLink></div><aside><EventTag type={event.event_type}/><More href={'/events/'+event.id}>{t('자세히 보기','Details')}</More></aside></article>)}</div>}{!result.loading&&!result.error&&!events.length&&<EmptyData title={t('선택한 기간의 이벤트가 없습니다','No events in the selected range')}/>} {result.data?.length===100&&<p className="pc-research-muted">{t('최근 100개 이벤트에서 조회합니다. 기간을 좁혀 확인하세요.','Showing the latest 100 events; narrow the date range for detail.')}</p>}</PcPanel><aside className="pc-research-stack"><PcPanel title={t('핵심 모니터링 포인트','Key monitoring points')} icon="shield"><div className="pc-monitor-list numbered">{company.events.slice(0,5).map((item,index)=><MonitoringRow key={item.id} item={item} index={index}/>)}</div>{!company.events.length&&<EmptyData/>}</PcPanel><PcPanel title={t('다음 주요 일정','Upcoming dates')} icon="calendar"><PcDataState {...calendar} retry={calendar.reload}/>{nextDates.length?<div className="pc-timeline-next">{nextDates.slice(0,2).map(item=><div key={item.id}><time>{date(item.occurs_on,'date')}</time><strong>{item.title}</strong><p>{item.quote||t('등록된 확인 일정','Saved research date')}</p></div>)}<Link className="pc-button pc-secondary" href="/calendar"><Icon name="calendar"/>{t('캘린더에서 보기','Open calendar')}</Link></div>:!calendar.loading&&!calendar.error?<EmptyData title={t('확인된 예정 일정이 없습니다','No confirmed upcoming dates')}/>:null}</PcPanel><PcPanel title={t('관련 링크','Related links')} icon="file"><ResourceList items={company.documents.slice(0,3)}/></PcPanel></aside></div></>;
}

export function DesktopEvent({id,panel}:{id:string;panel?:string}){return <EventContent key={id} id={id} panel={panel}/>;}
function EventContent({id,panel}:{id:string;panel?:string}){
 const {token}=useAuth(),{text:t,date}=usePrefs(),result=useResource('/v1/events/'+encodeURIComponent(id),detailSchema),resource=useData({action:'resource',p:{kind:'event',id}},resourceSchema),action=useMutation();
 const [saved,setSaved]=useState<boolean|null>(null),[selected,setSelected]=useState<Evidence|null>(null),[provenance,setProvenance]=useState(false);
 const detail=result.data,companyId=detail?.event.company.id,company=useData(companyId?{action:'company',p:{id:companyId}}:null,companyDetailSchema),isSaved=saved??resource.data?.is_saved??false;
 useVisit(detail?resource.data:null);
 function save(){void action.run(async()=>{const response=await workspace(token,{action:'save',p:{kind:'event',id,saved:!isSaved}},savedSchema);setSaved(response.saved);});}
 async function share(){await action.run(async()=>{if(!navigator.clipboard)throw new Error(t('이 브라우저에서는 링크 복사를 지원하지 않습니다. 주소창의 링크를 복사하세요.','Copy the URL from the address bar; clipboard access is unavailable.'));await navigator.clipboard.writeText(window.location.href);},t('페이지 링크를 복사했습니다.','Page link copied.'));}
 if(result.loading||result.error||!detail)return <div className="pc-research pc-event"><PcDataState {...result} retry={result.reload}/>{!result.loading&&!result.error&&<EmptyData title={t('이벤트를 확인할 수 없습니다','Event unavailable')}/>}</div>;
 const {event,brief,facts,changes,evidence}=detail,stock=event.company;
 const metrics=facts.filter(fact=>fact.value_raw!==null).slice(0,4),related=company.data?.events.filter(item=>item.id!==id).slice(0,3)??[];
 const evidenceFor=(factId:string)=>evidence.find(item=>item.fact_id===factId&&item.role==='current')??evidence.find(item=>item.fact_id===factId);
 const watch=<button className="pc-button" aria-pressed={company.data?.watching??false} disabled={action.busy||company.loading||!company.data} onClick={()=>void action.run(async()=>{await request('/v1/watchlist/'+encodeURIComponent(stock.id),token,emptySchema,body(company.data?.watching?'DELETE':'PUT'));company.reload();})}><Icon name="star" size={16}/>{t('관심종목','Watchlist')}</button>;
 return <article className={'pc-research pc-event '+(panel==='evidence'?'pc-event-evidence':'')}>
 {panel==='evidence'?<><Crumbs><Link href={'/companies/'+stock.id}>{stock.name}</Link><span>›</span><Link href={'/events/'+id}>{t('이벤트 상세','Event details')}</Link><span>›</span><strong>{t('근거 / 출처','Evidence / sources')}</strong></Crumbs><PcHeading title={t('근거 / 출처','Evidence / sources')} description={t('주요 주장에 대한 원문 근거와 출처를 확인하세요.','Review the original evidence and sources behind each claim.')}/><section className="pc-evidence-context"><PcLogo ticker={stock.ticker} size={65}/><div><Link href={'/companies/'+stock.id}><strong>{stock.name}</strong><span>{stock.ticker}</span></Link><p>{event.headline}</p><time>{date(event.published_at,event.publication_precision)} · {detail.document.provider.toUpperCase()}</time></div><More href={'/events/'+id}>{t('이벤트 상세로','Event details')}</More></section><EvidencePage detail={detail} onEvidence={setSelected}/></>:<>
 <div className="pc-event-toolbar"><Link href="/today">‹ {t('목록으로 돌아가기','Back to changes')}</Link><div><button className="pc-button" aria-label={isSaved?t('이벤트 저장 취소','Unsave event'):t('이벤트 저장','Save event')} aria-pressed={isSaved} disabled={action.busy||resource.loading||!!resource.error} onClick={save}><Icon name="star" size={16}/>{isSaved?t('저장됨','Saved'):t('저장','Save')}</button><button className="pc-button" onClick={()=>void share()} disabled={action.busy}><Icon name="upload" size={16}/>{t('공유','Share')}</button>{watch}</div></div>
 <div className="pc-research-columns pc-event-columns"><div className="pc-research-stack"><header className="pc-event-hero"><div className="pc-event-identity"><Link href={'/companies/'+stock.id}><PcLogo ticker={stock.ticker} size={92}/></Link><div><Link className="pc-event-company" href={'/companies/'+stock.id}>{stock.name}<span>{stock.ticker} · {stock.market}</span></Link><h1>{event.headline}</h1><div className="pc-event-meta"><time>{date(event.published_at,event.publication_precision)}</time><EventTag type={event.event_type}/><span className="pc-research-tag">{t('게시된 분석','Published analysis')}</span></div></div></div></header>
 <div className="pc-event-summary"><Icon name="spark" size={24}/><p><strong>{t('무엇이 바뀌었나요?','What changed?')}</strong>{brief.what_happened||event.what_happened}</p></div>
 {metrics.length>0&&<div className="pc-event-metrics">{metrics.map((fact,index)=><button type="button" className={'tone-'+index%4} key={fact.id} onClick={()=>{const found=evidenceFor(fact.id);if(found)setSelected(found);else setProvenance(true);}}><span><Icon name={index%2?'pie':'timeline'} size={20}/><FieldName field={fact.field}/></span><strong>{exact(fact.value_raw)}</strong><small>{[fact.unit,fact.period,fact.basis].filter(Boolean).join(' · ')}</small></button>)}</div>}
 <div className="pc-event-middle"><PcPanel title={t('왜 중요한가요?','Why does it matter?')} icon="spark"><p className="pc-research-prose">{brief.interpretation||t('게시된 해석이 없습니다.','No published interpretation is available.')}</p>{brief.uncertainty&&<div className="pc-event-uncertainty"><strong>{t('불확실성','Uncertainty')}</strong><p>{brief.uncertainty}</p></div>}</PcPanel><PcPanel title={t('이전 대비 달라진 점','Previous and current')} icon="timeline">{changes.length?<div className="pc-event-comparison"><table><thead><tr><th>{t('항목','Item')}</th><th>{t('이전','Previous')}</th><th>{t('현재','Current')}</th></tr></thead><tbody>{changes.slice(0,6).map(change=><tr key={change.id}><th><FieldName field={change.field}/></th><td>{exact(change.previous_value)}</td><td><button onClick={()=>{const found=evidenceFor(change.current_fact_id);if(found)setSelected(found);else setProvenance(true);}}>{exact(change.current_value)}</button>{change.percentage_change!==null&&<small>{exact(change.percentage_change)}%</small>}</td></tr>)}</tbody></table></div>:<EmptyData title={t('비교할 이전 근거가 없습니다','No previous evidence for comparison')}/>}</PcPanel></div>
 <div className="pc-event-middle"><PcPanel title={t('핵심 인사이트','Published interpretation')} icon="spark"><p className="pc-research-prose">{brief.interpretation||t('검토된 해석이 없습니다.','No reviewed interpretation is available.')}</p><Link className="pc-button" href={'/questions?event='+id}>{t('근거에 대해 질문하기','Ask about the evidence')}<Icon name="arrow" size={16}/></Link></PcPanel><PcPanel title={t('앞으로 확인할 것','What to monitor')} icon="shield"><p className="pc-research-prose">{brief.monitor_next||t('게시된 모니터링 항목이 없습니다.','No published monitoring points.')}</p><Link className="pc-button" href={'/companies/'+stock.id+'/timeline'}>{t('기업 타임라인 열기','Open company timeline')}<Icon name="arrow" size={16}/></Link></PcPanel></div>
 <PcPanel title={t('근거 자료','Source materials')} icon="file" action={<More href={'/events/'+id+'?panel=evidence'}>{t('근거 전체 보기','View all evidence')}</More>}><div className="pc-event-document"><span className="pc-research-file-icon red"><Icon name="file" size={25}/></span><div><Link href={'/documents/'+detail.document.id+'?kind=document'}><strong>{detail.document.title}</strong></Link><p>{detail.document.provider.toUpperCase()} · {date(detail.document.published_at,detail.document.publication_precision)}</p></div><SourceLink url={detail.document.source_url}>{t('원문 보기','Open source')}</SourceLink></div><button className="pc-research-more" type="button" onClick={()=>setProvenance(true)}>{t('수집 및 검증 정보','Collection and validation details')} ›</button></PcPanel>
 </div><aside className="pc-research-stack"><PcPanel title={stock.name+' ('+stock.ticker+')'} action={<More href={'/companies/'+stock.id}>{t('기업 개요','Overview')}</More>}><Quote ticker={stock.ticker}/><dl className="pc-research-key-values"><div><dt>{t('시장','Market')}</dt><dd>{stock.market}</dd></div><div><dt>{t('출처','Source')}</dt><dd>{event.source_provider.toUpperCase()}</dd></div><div><dt>{t('원문 근거','Source evidence')}</dt><dd>{evidence.length}{t('개',' items')}</dd></div></dl><Link className="pc-button pc-button-primary pc-research-full" href={'/companies/'+stock.id}>{t('기업 개요 보기','View company overview')}<Icon name="arrow" size={16}/></Link></PcPanel><PcPanel title={t('관련 이벤트','Related events')} icon="clock" action={<More href={'/companies/'+stock.id+'/timeline'}/>}><PcDataState {...company} retry={company.reload}/><ResourceList items={related}/></PcPanel><PcPanel title={t('분석 기준','Analysis basis')} icon="shield"><dl className="pc-research-key-values"><div><dt>{t('원문 제공자','Source provider')}</dt><dd>{detail.document.provider}</dd></div><div><dt>{t('검증 결과','Validation results')}</dt><dd>{detail.validations.length}{t('개',' checks')}</dd></div><div><dt>{t('분석 버전','Analysis version')}</dt><dd>{brief.template_version}</dd></div></dl><p className="pc-research-muted">{t('확인된 사실과 게시된 해석을 구분하며, 근거가 없는 전망은 제공하지 않습니다.','Published interpretations are distinct from source facts; unsupported forecasts are not supplied.')}</p></PcPanel></aside></div></>}
 <PcNotice action={action}/>{resource.error&&<PcDataState loading={false} error={resource.error} retry={resource.reload}/>}
 {selected&&<EvidenceDialog evidence={selected} detail={detail} onClose={()=>setSelected(null)}/>}
 {provenance&&<PcModal title={t('수집 및 검증 정보','Collection and validation details')} onClose={()=>setProvenance(false)}><dl className="pc-research-key-values"><div><dt>{t('수집 시각','Ingested at')}</dt><dd>{date(detail.document.ingested_at)}</dd></div><div><dt>{t('발행 시간대','Publication timezone')}</dt><dd>{detail.document.publication_timezone}</dd></div><div><dt>{t('원문 SHA-256','Document SHA-256')}</dt><dd>{detail.document.raw_sha256}</dd></div><div><dt>{t('분석 버전','Analysis version')}</dt><dd>{detail.run.pipeline_version}</dd></div></dl><SourceLink url={detail.document.source_url}>{t('공식 원문','Original source')}</SourceLink><div className="pc-event-validations">{detail.validations.map((item,index)=><p key={item.claim_key+index}><strong>{item.claim_key+' · '+item.status}</strong><span>{item.reason}</span></p>)}</div></PcModal>}
 </article>;
}
function EvidenceDialog({evidence,detail,onClose}:{evidence:Evidence;detail:EventDetail;onClose:()=>void}){
 const {text:t,date}=usePrefs();return <PcModal title={t('원문 근거','Source evidence')} onClose={onClose}><div className="pc-evidence-dialog-meta"><strong>{evidence.source_name}</strong><span>{evidence.role==='previous'?t('이전 근거','Previous evidence'):t('현재 근거','Current evidence')}</span><time>{date(evidence.published_at,evidence.publication_precision)}</time></div><blockquote className="pc-research-full-quote">{evidence.quote}</blockquote><p className="pc-research-muted">{evidence.location}</p><SourceLink url={evidence.source_url}>{t('공식 원문 열기','Open official source')}</SourceLink>{evidence.document_id===detail.document.id&&<details className="pc-research-provenance"><summary>{t('원문 식별 정보','Source provenance')}</summary><dl><dt>SHA-256</dt><dd>{detail.document.raw_sha256}</dd><dt>{t('수집 시각','Ingested at')}</dt><dd>{date(detail.document.ingested_at)}</dd></dl></details>}</PcModal>;
}
function EvidencePage({detail,onEvidence}:{detail:EventDetail;onEvidence:(evidence:Evidence)=>void}){
 const {text:t,date}=usePrefs(),[tab,setTab]=useState('sources'),[provider,setProvider]=useState(''),[tier,setTier]=useState(''),[role,setRole]=useState('');
 const {event,evidence,facts}=detail,providers=[...new Set(evidence.map(item=>item.source_name))],tiers=[...new Set(evidence.map(item=>item.source_tier).filter(value=>value!==null))];
 const filtered=evidence.filter(item=>(!provider||item.source_name===provider)&&(!tier||String(item.source_tier)===tier)&&(!role||item.role===role));
 const documents=[...new Map(filtered.map(item=>[item.document_id,item])).values()];
 const forClaim=(factId:string)=>{const ids=new Set([factId,...detail.changes.filter(change=>change.current_fact_id===factId&&change.previous_fact_id).map(change=>change.previous_fact_id!)]);return filtered.filter(item=>ids.has(item.fact_id));};
 const claims=facts.filter(fact=>!provider&&!tier&&!role||forClaim(fact.id).length>0);
 return <><nav className="pc-research-tabs" aria-label={t('근거 표시 방식','Evidence view')}><button aria-pressed={tab==='sources'} onClick={()=>setTab('sources')}>{t('주요 근거 자료','Source materials')}</button><button aria-pressed={tab==='claims'} onClick={()=>setTab('claims')}>{t('핵심 주장별 출처 매핑','Claim-to-source mapping')}</button></nav><div className="pc-research-columns pc-evidence-columns"><PcPanel title={tab==='sources'?t('주요 근거 자료','Source materials'):t('핵심 주장별 출처 매핑','Claim-to-source mapping')} icon="file"><div className="pc-evidence-filters"><select aria-label={t('출처 제공자 필터','Source provider filter')} value={provider} onChange={e=>setProvider(e.target.value)}><option value="">{t('전체 출처','All providers')}</option>{providers.map(name=><option key={name}>{name}</option>)}</select><select aria-label={t('출처 등급 필터','Source tier filter')} value={tier} onChange={e=>setTier(e.target.value)}><option value="">{t('모든 출처 등급','All source tiers')}</option>{tiers.map(value=><option key={value} value={value!}>{t('출처 등급 ','Source tier ')+value}</option>)}</select><select aria-label={t('근거 시점 필터','Evidence period filter')} value={role} onChange={e=>setRole(e.target.value)}><option value="">{t('전체 시점','All periods')}</option><option value="current">{t('현재 근거','Current evidence')}</option><option value="previous">{t('이전 근거','Previous evidence')}</option></select></div>
 {tab==='sources'?<div className="pc-evidence-sources">{documents.map((source,index)=>{const entries=filtered.filter(item=>item.document_id===source.document_id);return <article className="pc-evidence-source" key={source.document_id}><header><span className={'pc-research-file-icon '+(index%2?'blue':'red')}><Icon name="file" size={29}/></span><div><Link href={'/documents/'+source.document_id+'?kind=document'}><h3>{source.document_id===detail.document.id?detail.document.title:source.source_name}</h3></Link><p>{source.source_name.toUpperCase()} · {date(source.published_at,source.publication_precision)}</p></div><SourceLink url={source.source_url}>{t('원문 보기','Open source')}</SourceLink></header>{entries.map((item,i)=><div className="pc-evidence-source-quote" key={item.fact_id+item.role+i}><div><span className="pc-research-tag">{item.role==='previous'?t('이전 근거','Previous evidence'):t('현재 근거','Current evidence')}</span><span>{item.location}</span></div><blockquote>{item.quote}</blockquote><button type="button" onClick={()=>onEvidence(item)}>{t('인용 전문 보기','Read full quote')} ›</button></div>)}<footer><span><Icon name="shield" size={15}/>{source.source_tier===null?t('출처 등급 미제공','Source tier unavailable'):t('출처 등급 ','Source tier ')+source.source_tier}</span><span>{t('연결된 근거 ','Linked evidence ')+entries.length}</span></footer></article>;})}</div>:<div className="pc-evidence-mappings">{claims.map((fact,index)=><article key={fact.id}><header><span>{index+1}</span><h3><FieldName field={fact.field}/> · {exact(fact.value_raw)} {fact.unit}</h3></header><blockquote>{fact.quote}</blockquote><div>{forClaim(fact.id).map((item,i)=><button className="pc-button" key={item.chunk_id+item.role+i} onClick={()=>onEvidence(item)}><Icon name="file" size={15}/>{item.source_name} · {item.role==='previous'?t('이전','Previous'):t('현재','Current')}</button>)}</div>{!forClaim(fact.id).length&&<p className="pc-research-muted">{t('연결된 인용 위치가 없습니다. 이벤트의 원문을 확인하세요.','No linked citation location. Read the event source.')}</p>}</article>)}</div>}
 {!filtered.length&&<EmptyData title={t('선택한 조건의 근거가 없습니다','No evidence matches these filters')}/>}<p className="pc-evidence-note"><Icon name="shield" size={17}/>{t('인용문과 위치는 저장된 원문 근거입니다. 출처 등급은 수집 당시의 분류이며 신뢰 확률이 아닙니다.','Quotes and locations are stored source evidence. Source tiers describe provenance, not a probability of reliability.')}</p></PcPanel><aside className="pc-research-stack"><PcPanel title={t('핵심 주장별 출처 매핑','Claim-to-source mapping')} icon="shield"><div className="pc-evidence-claims">{claims.map((fact,index)=><article className="pc-evidence-claim" key={fact.id}><h3><span>{index+1}</span><FieldName field={fact.field}/>{fact.value_raw!==null&&<> · {exact(fact.value_raw)} {fact.unit}</>}</h3><blockquote>{fact.quote}</blockquote><p>{[fact.period,fact.basis].filter(Boolean).join(' · ')}</p><div>{forClaim(fact.id).map((item,i)=><button key={item.chunk_id+item.role+i} onClick={()=>onEvidence(item)}><Icon name="file" size={14}/>{item.source_name} · {item.location}</button>)}</div></article>)}</div>{!claims.length&&<EmptyData title={t('게시된 핵심 주장이 없습니다','No published claims')}/>}</PcPanel><Link href={'/questions?event='+event.id} className="pc-evidence-ask"><Icon name="spark" size={24}/><div><strong>{t('근거가 더 필요하신가요?','Need more evidence?')}</strong><p>{t('AI 후속 질문으로 원문 근거를 확인하세요.','Ask a follow-up about the stored sources.')}</p></div><span>›</span></Link></aside></div></>;
}

export function DesktopDocument({id,kind='document'}:{id:string;kind?:'document'|'filing'}){return <DocumentContent key={kind+':'+id} id={id} kind={kind}/>;}
function DocumentContent({id,kind}:{id:string;kind:'document'|'filing'}){
 const {token}=useAuth(),{text:t,date}=usePrefs(),result=useData({action:'document_detail',p:{id,kind}},documentDetailSchema),action=useMutation();
 const [saved,setSaved]=useState<boolean|null>(null),[section,setSection]=useState<DocumentSection|null>(null),[fact,setFact]=useState<DocumentFact|null>(null),[chooseEvent,setChooseEvent]=useState(false),[showAll,setShowAll]=useState(false),[allFacts,setAllFacts]=useState(false),[moreSections,setMoreSections]=useState<DocumentSection[]>([]),[nextOffset,setNextOffset]=useState<number|null|undefined>();
 const data=result.data,item=data?.document,isSaved=saved??item?.is_saved??false,sections=[...(data?.sections??[]),...moreSections],next=nextOffset===undefined?data?.next_section_offset:nextOffset,metrics=data?.facts.filter(entry=>entry.value_raw!==null)??[];
 useVisit(item);
 function save(){void action.run(async()=>{const response=await workspace(token,{action:'save',p:{kind,id,saved:!isSaved}},savedSchema);setSaved(response.saved);});}
 function loadMore(){if(next==null)return;void action.run(async()=>{const response=await workspace(token,{action:'document_detail',p:{id,kind,section_offset:next}},documentDetailSchema);setMoreSections(previous=>{const known=new Set([...(data?.sections??[]),...previous].map(entry=>entry.id));return [...previous,...response.sections.filter(entry=>!known.has(entry.id))];});setNextOffset(response.next_section_offset);});}
 return <article className="pc-research pc-document"><Crumbs><Link href="/saved?kind=document">{t('자료실','Documents')}</Link><span>›</span>{item&&<><Link href={'/companies/'+item.company_id}>{item.company_name+' ('+item.ticker+')'}</Link><span>›</span></>}<strong>{t('문서 상세','Document details')}</strong></Crumbs><PcDataState {...result} retry={result.reload}/><PcNotice action={action}/>{data&&item&&<><header className="pc-document-hero"><span className={'pc-document-file '+(data.metadata.mime_type==='application/pdf'?'is-pdf':'')}><Icon name="file" size={46}/>{data.metadata.mime_type==='application/pdf'&&<b>PDF</b>}</span><div><h1>{item.title}</h1><p><Link href={'/companies/'+item.company_id}>{item.company_name+' ('+item.ticker+')'}</Link><span> · {date(item.published_at,item.publication_precision)} · {data.metadata.provider.toUpperCase()}</span></p><span className="pc-research-tag">{item.category}</span></div><div className="pc-document-hero-actions"><SourceLink url={item.source_url} className="pc-button pc-button-primary">{t('원문 보기','Open source')}</SourceLink><button className="pc-button" disabled={action.busy} aria-label={isSaved?t('문서 저장 취소','Unsave document'):t('문서 저장','Save document')} aria-pressed={isSaved} onClick={save}><Icon name="star" size={16}/>{isSaved?t('저장됨','Saved'):t('저장','Save')}</button></div></header>
 <div className="pc-research-columns pc-document-columns"><div className="pc-research-stack"><PcPanel title={t('핵심 요약','Key takeaways')} icon="file" action={<span className="pc-document-reviewed"><Icon name="shield" size={15}/>{t('게시된 분석','Published analysis')}</span>}>{data.summaries.length?<div className="pc-document-summaries">{data.summaries.map((entry,index)=><Link key={entry.event_id+index} href={'/events/'+entry.event_id}><span>{index+1}</span><div><h3>{entry.title}</h3><p>{entry.text}</p></div></Link>)}</div>:<EmptyData title={t('게시된 요약이 없습니다','No published summary')}/>} {data.counts.summaries>data.summaries.length&&<p className="pc-research-muted">{t('공개 요약 ','Published summaries ')+data.summaries.length+' / '+data.counts.summaries}</p>}</PcPanel>
 {metrics.length>0&&<div className="pc-document-metrics">{(allFacts?metrics:metrics.slice(0,4)).map((entry,index)=><button className={'tone-'+index%4} key={entry.id} onClick={()=>setFact(entry)}><span><FieldName field={entry.field}/></span><strong>{exact(entry.value_raw)}</strong><small>{[entry.unit,entry.period,entry.basis].filter(Boolean).join(' · ')}</small></button>)}</div>}{metrics.length>4&&<button className="pc-research-more" onClick={()=>setAllFacts(value=>!value)} aria-expanded={allFacts}>{allFacts?t('지표 접기','Show fewer metrics'):t('전체 지표 보기','View all metrics')} ({metrics.length})</button>}{data.counts.facts>data.facts.length&&<p className="pc-research-muted">{t('공개된 사실 ','Public facts ')+data.facts.length+' / '+data.counts.facts}</p>}
 <PcPanel title={t('목차','Contents')} icon="file" action={<span className="pc-research-muted">{t('총 ','')+data.sections_total+t('개 근거 구간',' evidence sections')}</span>}>{sections.length?<div className="pc-document-toc">{(showAll?sections:sections.slice(0,4)).map((entry,index)=><button key={entry.id} type="button" aria-label={`${index+1}. ${entry.title||entry.location} ${t('내용 열기','Open section')}`} onClick={()=>setSection(entry)}><span>{index+1}</span><div><strong>{entry.title||entry.location}</strong><small>{entry.location}</small></div><span>{entry.page_start!==null?entry.page_start+(entry.page_end!==null&&entry.page_end!==entry.page_start?'–'+entry.page_end:'')+t('페이지',' pages'):t('원문 구간','Source section')}</span><span>›</span></button>)}</div>:<EmptyData title={t('공개된 근거 구간이 없습니다','No public source sections')}/>} {sections.length>4&&<button className="pc-research-more" aria-expanded={showAll} onClick={()=>setShowAll(value=>!value)}>{showAll?t('목차 접기','Show fewer sections'):t('목차 전체 보기','View all sections')} ›</button>}{showAll&&next!=null&&<button className="pc-button" disabled={action.busy} onClick={loadMore}>{t('근거 구간 더 보기','Load more source sections')}</button>}<p className="pc-document-source-note">{t('검토된 사실에 연결된 원문 구간입니다. 전체 문서는 공식 원문에서 확인하세요.','These source sections support reviewed facts. Read the complete document at the official source.')}</p></PcPanel>
 </div><aside className="pc-research-stack"><PcPanel title={t('문서 정보','Document information')} icon="file"><dl className="pc-research-key-values"><div><dt>{t('기업명','Company')}</dt><dd>{item.company_name}</dd></div><div><dt>{t('종목코드','Ticker')}</dt><dd>{item.ticker}</dd></div><div><dt>{t('제공자','Provider')}</dt><dd>{data.metadata.provider.toUpperCase()}</dd></div><div><dt>{t('문서 유형','Document type')}</dt><dd>{item.category||t('미제공','Unavailable')}</dd></div><div><dt>{t('발행일','Published')}</dt><dd>{date(item.published_at,item.publication_precision)}</dd></div><div><dt>{t('파일 형식','File format')}</dt><dd>{data.metadata.mime_type??t('미제공','Unavailable')}</dd></div><div><dt>{t('파일 크기','File size')}</dt><dd>{data.metadata.size_bytes!==null?data.metadata.size_bytes.toLocaleString()+' bytes':t('미제공','Unavailable')}</dd></div><div><dt>{t('페이지 수','Page count')}</dt><dd>{data.metadata.page_count??t('미제공','Unavailable')}</dd></div></dl><SourceLink url={item.source_url} className="pc-button pc-research-full">{t('공식 원문 바로가기','Open official source')}</SourceLink><details className="pc-research-provenance"><summary>{t('출처 및 수집 정보','Source provenance')}</summary><dl><dt>{t('발행 시간대','Publication timezone')}</dt><dd>{data.metadata.publication_timezone??t('미제공','Unavailable')}</dd><dt>{t('수집 시각','Ingested at')}</dt><dd>{date(data.metadata.ingested_at)}</dd>{data.metadata.raw_sha256&&<><dt>{kind==='filing'?t('SEC 제출 목록 SHA-256','SEC submissions SHA-256'):t('원문 SHA-256','Document SHA-256')}</dt><dd>{data.metadata.raw_sha256}</dd></>}</dl></details></PcPanel><PcPanel title={item.company_name+' ('+item.ticker+')'} action={<More href={'/companies/'+item.company_id}/> }><Quote ticker={item.ticker}/><Link className="pc-button pc-research-full" href={'/companies/'+item.company_id}>{t('기업 개요 보기','View company overview')}<Icon name="arrow" size={16}/></Link></PcPanel><PcPanel title={t('관련 문서','Related documents')} icon="file" action={<More href={'/search?q='+encodeURIComponent(item.ticker)+'&kind=document'}/>}><ResourceList items={data.related.slice(0,3)}/>{data.counts.related>3&&<p className="pc-research-muted">{t('관련 문서 ','Related documents ')+data.counts.related}</p>}</PcPanel></aside></div>
 <section className="pc-document-ask"><span><Icon name="spark" size={29}/></span><div><h2>{t('이 문서로 AI에게 질문하기','Ask AI about this document')}</h2><p>{data.events.length?t('복잡한 수치와 주장에 대해 검토된 원문 근거에서 답을 찾아보세요.','Find answers in reviewed source evidence for the document’s facts and claims.'):t('질문할 수 있는 게시된 이벤트가 아직 없습니다. 공식 원문을 확인해 주세요.','No published event is available for evidence questions yet. Read the official source.')}</p></div>{data.events.length===1?<Link className="pc-button pc-button-primary" href={'/questions?event='+data.events[0].id}>{t('AI에게 질문하기','Ask AI')}<Icon name="arrow" size={16}/></Link>:data.events.length>1?<button className="pc-button pc-button-primary" onClick={()=>setChooseEvent(true)}>{t('AI에게 질문하기','Ask AI')}<Icon name="arrow" size={16}/></button>:null}</section></>}
 {section&&<PcModal title={section.title||section.location} onClose={()=>setSection(null)}><p className="pc-research-muted">{section.location}</p><div className="pc-document-section-content">{section.content}</div><SourceLink url={item?.source_url??null}>{t('공식 원문 열기','Open official source')}</SourceLink></PcModal>}
 {fact&&<PcModal title={(fieldLabels[fact.field]?t(...fieldLabels[fact.field]):fact.field)+' · '+t('원문 근거','Source evidence')} onClose={()=>setFact(null)}><p className="pc-document-fact-value">{exact(fact.value_raw)} {fact.unit}</p><p className="pc-research-muted">{[fact.period,fact.basis,fact.location].filter(Boolean).join(' · ')}</p><blockquote className="pc-research-full-quote">{fact.quote}</blockquote><SourceLink url={fact.source_url}>{t('공식 원문 열기','Open official source')}</SourceLink><Link className="pc-button" href={'/events/'+fact.event_id+'?panel=evidence'}>{t('연결된 이벤트 근거','Linked event evidence')}<Icon name="arrow" size={16}/></Link></PcModal>}
 {chooseEvent&&data&&<PcModal title={t('질문할 이벤트 선택','Choose an event to ask about')} onClose={()=>setChooseEvent(false)}><p className="pc-research-muted">{t('선택한 이벤트에 저장된 원문 근거에서 답을 찾습니다.','Answers use source evidence saved for the selected event.')}</p><div className="pc-document-event-options">{data.events.map(entry=><Link className="pc-button" key={entry.id} href={'/questions?event='+entry.id}>{entry.title}<Icon name="arrow" size={16}/></Link>)}</div></PcModal>}
 </article>;
}
